function paintSwampOverlayRevival(ctx, tile, sx, sy, size) {
  const fertility = tile.climate?.fertility ?? 0.55;
  const vegetation = tile.climate?.vegetation ?? 0.55;
  const moisture = tile.climate?.moisture ?? 0.65;
  ctx.save();
  // Scattered moss flecks and organic debris — replaces the old solid tile wash
  // so the swamp surface feels organic rather than stamped.
  const baseSeed = tile.wx * 313 + tile.wy * 997;
  for (let gy = 0; gy < 8; gy++) {
    for (let gx = 0; gx < 8; gx++) {
      const cellSeed = baseSeed + gy * 19 + gx * 23;
      const px = sx + gx * 4 + ((cellSeed * 13) % 4);
      const py = sy + gy * 4 + ((cellSeed * 37) % 4);
      const presence = ((cellSeed * 53) % 100) / 100;
      const mossChance = 0.16 + (fertility * 0.36 + vegetation * 0.44 + moisture * 0.20) * 0.36;
      if (presence < mossChance) {
        const alpha = 0.06 + (cellSeed % 5) * 0.04;
        ctx.fillStyle = `rgba(52, 96, 48, ${alpha.toFixed(3)})`;
        ctx.fillRect(px, py, 2 + (cellSeed % 3), 1 + (cellSeed % 2));
      }
    }
  }
  // Dark wet depression — small, not tile-wide
  const wet = smoothNoise(tile.wx + 11, tile.wy - 7, 9, 16032);
  if (wet > 0.52) {
    ctx.fillStyle = `rgba(25, 42, 34, ${((wet - 0.52) * 0.38).toFixed(3)})`;
    const px = sx + Math.floor(smoothNoise(tile.wx, tile.wy, 3, 16033) * (size - 8)) + 4;
    const py = sy + Math.floor(smoothNoise(tile.wx + 5, tile.wy - 3, 3, 16034) * (size - 8)) + 4;
    ctx.fillRect(px, py, Math.max(3, Math.floor(size * (0.08 + wet * 0.22))), Math.max(2, Math.floor(size * (0.06 + wet * 0.14))));
  }
  ctx.restore();
}

