const fs=require('fs');
let c=fs.readFileSync('src/render/tile-painter.js','utf8');

// Remove the debug marker I added
c=c.replace(/  \/\/ DEBUG: paintSwampMacroObjects executing[\s\S]*?ctx\.restore\(\);\n/g, '');

// Find the macro function and replace it with a simpler, guaranteed-visible version
const s=c.indexOf('function paintSwampMacroObjects');
const e=c.indexOf('function paintPixelLabBase', s);
const oldFn=c.substring(s, e);

const newFn=`function paintSwampMacroObjects(ctx, tile, sx, sy, size) {
  // Large visible swamp objects: 1-3 per tile, drawn at high opacity
  const count = 1 + Math.floor(rand2(tile.wx, tile.wy, 16500) * 2);
  for (let i = 0; i < count; i++) {
    const px = sx + Math.floor(rand2(tile.wx, tile.wy, 16510 + i * 7) * (size - 14)) + 7;
    const py = sy + Math.floor(rand2(tile.wx, tile.wy, 16511 + i * 7) * (size - 14)) + 7;
    const kind = Math.floor(rand2(tile.wx, tile.wy, 16520 + i) * 4);
    ctx.save();
    if (kind === 0) {
      // Standing dead snag — dark brown trunk
      const h = size * (0.35 + rand2(tile.wx, tile.wy, 16530 + i) * 0.30);
      const w = size * (0.08 + rand2(tile.wx, tile.wy, 16531 + i) * 0.06);
      ctx.fillStyle = 'rgba(36,22,16,0.95)';
      ctx.fillRect(px - w/2, py - h, w, h);
      ctx.strokeStyle = 'rgba(56,36,24,0.70)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(px + w/2, py - h * 0.6);
      ctx.lineTo(px + w + size*0.08, py - h * 0.7);
      ctx.stroke();
    } else if (kind === 1) {
      // Tree stump — wide flat oval
      const sw = size * (0.18 + rand2(tile.wx, tile.wy, 16540 + i) * 0.16);
      const sh = size * (0.06 + rand2(tile.wx, tile.wy, 16541 + i) * 0.05);
      ctx.fillStyle = 'rgba(52,34,22,0.95)';
      ctx.beginPath();
      ctx.ellipse(px, py, sw, sh, 0, 0, Math.PI*2);
      ctx.fill();
      ctx.fillStyle = 'rgba(72,48,30,0.85)';
      ctx.beginPath();
      ctx.ellipse(px, py - sh*0.15, sw*0.6, sh*0.4, 0, 0, Math.PI*2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(100,68,40,0.60)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.ellipse(px, py, sw*0.4, sh*0.25, 0, 0, Math.PI*2);
      ctx.stroke();
    } else if (kind === 2) {
      // Fallen log — thick rotated brown oval
      const lw = size * (0.22 + rand2(tile.wx, tile.wy, 16550 + i) * 0.22);
      const lh = size * (0.06 + rand2(tile.wx, tile.wy, 16551 + i) * 0.05);
      const rot = rand2(tile.wx, tile.wy, 16552 + i) * Math.PI;
      ctx.fillStyle = 'rgba(48,28,18,0.92)';
      ctx.translate(px, py);
      ctx.rotate(rot);
      ctx.beginPath();
      ctx.ellipse(0, 0, lw, lh, 0, 0, Math.PI*2);
      ctx.fill();
      ctx.strokeStyle = 'rgba(30,16,10,0.60)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(-lw*0.6, -lh*0.1);
      ctx.lineTo(lw*0.5, lh*0.15);
      ctx.stroke();
    } else {
      // Large rock — grey bumpy oval with highlight
      const rw = size * (0.12 + rand2(tile.wx, tile.wy, 16560 + i) * 0.14);
      const rh = size * (0.08 + rand2(tile.wx, tile.wy, 16561 + i) * 0.08);
      ctx.fillStyle = 'rgba(68,64,58,0.92)';
      ctx.beginPath();
      ctx.ellipse(px, py, rw, rh, 0, 0, Math.PI*2);
      ctx.fill();
      ctx.fillStyle = 'rgba(98,94,84,0.50)';
      ctx.beginPath();
      ctx.ellipse(px - rw*0.15, py - rh*0.15, rw*0.4, rh*0.3, 0, 0, Math.PI*2);
      ctx.fill();
    }
    ctx.restore();
  }
  tile.swampMacroLayer = count + ' macro-objs';
}
`;

c = c.replace(oldFn, newFn);
fs.writeFileSync('src/render/tile-painter.js', c);
console.log('Macro function replaced. Size:', c.length);
"

