  ctx.beginPath();
  ctx.moveTo(sx + 2, sy + 2);
  ctx.lineTo(sx + size - 2, sy + size - 2);
  ctx.moveTo(sx + size - 2, sy + 2);
  ctx.lineTo(sx + 2, sy + size - 2);
  ctx.stroke();
  ctx.restore();
  var n = 1 + Math.floor(rand2(tile.wx, tile.wy, 16500) * 2);

