  let image = pixelBaseCache.get(src);
  if (!image) {
    image = new Image();
    image.decoding = 'async';
    image.src = src;
    pixelBaseCache.set(src, image);
  }
  return image;
}

function preparedPixelBaseCanvas(src, baseFamily) {
  const image = pixelBaseImage(src);
  if (!image?.complete || !(image.naturalWidth || image.width)) return null;
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  const key = `${src}|${baseFamily}|${width}x${height}|normalized-v1`;
  if (preparedPixelBaseCache.has(key)) return preparedPixelBaseCache.get(key);

  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const pctx = canvas.getContext('2d');
  pctx.imageSmoothingEnabled = false;
  pctx.drawImage(image, 0, 0);

  const data = pctx.getImageData(0, 0, width, height);
  const target = PIXEL_BASE_TARGET_RGB[baseFamily];
  if (target) {
    let r = 0, g = 0, b = 0, n = 0;
    // Ignore generator borders when measuring the tile's color. Several variants
    // have bright/dark frame pixels, and using them raw caused visible grid seams.
    for (let y = 2; y < height - 2; y++) {
      for (let x = 2; x < width - 2; x++) {
        const i = (y * width + x) * 4;
        const a = data.data[i + 3] / 255;
        if (a <= 0.01) continue;
        r += data.data[i] * a;
        g += data.data[i + 1] * a;
        b += data.data[i + 2] * a;
        n += a;
      }
    }
    if (n > 0) {
      const dr = target[0] - (r / n);
      const dg = target[1] - (g / n);
      const db = target[2] - (b / n);
      for (let i = 0; i < data.data.length; i += 4) {
        data.data[i] = clamp(data.data[i] + dr * 0.72, 0, 255);
        data.data[i + 1] = clamp(data.data[i + 1] + dg * 0.72, 0, 255);
        data.data[i + 2] = clamp(data.data[i + 2] + db * 0.72, 0, 255);
        data.data[i + 3] = 255;
      }
      pctx.putImageData(data, 0, 0);
    }
  }

  preparedPixelBaseCache.set(key, canvas);
  return canvas;
}

function pixelBaseInteriorVariantIndex(tile, variants) {
  if (!variants?.length) return 0;
  const macroX = Math.floor(tile.wx / 4);
  const macroY = Math.floor(tile.wy / 4);
  const primary = Math.floor(rand2(macroX, macroY, 16001) * variants.length) % variants.length;
  if (rand2(tile.wx, tile.wy, 16002) < 0.22) {
    return Math.floor(rand2(Math.floor(tile.wx / 2), Math.floor(tile.wy / 2), 16003) * variants.length) % variants.length;
  }
  return primary;
}

function pixelBaseTransform(tile) {
  const h = Math.floor(rand2(tile.wx, tile.wy, 16004) * 8) & 7;
  return {
    rotate: h & 3,
    flip: (h & 4) !== 0
  };
}

function drawPreparedPixelBase(ctx, canvas, tile, sx, sy, size, allowTransform) {
  const previousSmoothing = ctx.imageSmoothingEnabled;
  ctx.imageSmoothingEnabled = true;
  const inset = allowTransform ? 1 : 0;
  const sourceWidth = Math.max(1, canvas.width - inset * 2);
  const sourceHeight = Math.max(1, canvas.height - inset * 2);
  if (!allowTransform) {
    ctx.drawImage(canvas, inset, inset, sourceWidth, sourceHeight, sx, sy, size, size);
    ctx.imageSmoothingEnabled = previousSmoothing;
    return;
  }

  const { rotate, flip } = pixelBaseTransform(tile);
  ctx.save();
  ctx.translate(sx + size / 2, sy + size / 2);
  ctx.rotate(rotate * Math.PI / 2);
  ctx.scale(flip ? -1 : 1, 1);
  ctx.drawImage(canvas, inset, inset, sourceWidth, sourceHeight, -size / 2, -size / 2, size, size);
  ctx.restore();
  ctx.imageSmoothingEnabled = previousSmoothing;
}

for (const variants of Object.values(PIXEL_BASE_WANG_VARIANTS)) {
  for (const src of variants) pixelBaseImage(src);
}
for (const variants of Object.values(PIXEL_BASE_TILE_VARIANTS)) {
  for (const src of variants) pixelBaseImage(src);
}

function paintPixelLabBase(ctx, tile, recipe, sx, sy, size) {
  if (tile.pixelLabSkipBase) return false;
  const baseFamily = recipe?.base?.family ?? recipe?.baseFamily;
  const wangVariants = PIXEL_BASE_WANG_VARIANTS[baseFamily];
  const variants = PIXEL_BASE_TILE_VARIANTS[baseFamily];
  const mask = Number.isInteger(tile.pixelLabBaseMask) ? tile.pixelLabBaseMask : 15;
  const wangSrc = mask !== 15 ? wangVariants?.[mask] : null;
  const variantIndex = pixelBaseInteriorVariantIndex(tile, variants);
  const variantSrc = variants?.[variantIndex];
  const src = wangSrc || variantSrc || wangVariants?.[15];
  if (!src) return false;
  tile.pixelLabBaseSrc = src;
  tile.pixelLabBaseVariantSrc = variantSrc && !wangSrc ? `v${String(variantIndex).padStart(3, '0')}` : '';
  tile.pixelLabBaseFamily = baseFamily ?? 'none';
  tile.pixelLabBaseMask = mask;
  const canvas = preparedPixelBaseCanvas(src, baseFamily);
  if (!canvas) return false;
  drawPreparedPixelBase(ctx, canvas, tile, sx, sy, size, !wangSrc);
  return true;
}

