import { rand2, smoothNoise } from '../core/random.js';
import { paletteFor } from './palette.js';
import { paintMicroLayers } from './micro-layer-painter.js';

// ============================================================
// PixelLab base config — caches & image pools
// ============================================================
const pixelBaseCache = new Map();
const preparedPixelBaseCache = new Map();

const PIXEL_BASE_TARGET_RGB = Object.freeze({
  'swamp/wet_mud': [73, 52, 34],
  'swamp/mud_pool': [24, 24, 18]
});

const PIXEL_BASE_FOUNDATION_SRC = Object.freeze({
  'swamp/wet_mud': 'assets/pixelab/landscape_v2/base/swamp_wet_mud/tiles/swamp_wet_mud__tile__v000.png',
  'swamp/mud_pool': 'assets/pixelab/landscape_v2/base/swamp_mud_pool/tiles/swamp_mud_pool__tile__v000.png'
});

const PIXEL_BASE_TILE_VARIANTS = Object.freeze({
  'swamp/wet_mud': Array.from({ length: 16 }, (_, i) =>
    `assets/pixelab/landscape_v2/base/swamp_wet_mud/tiles/swamp_wet_mud__tile__v${String(i).padStart(3, '0')}.png`),
  'swamp/mud_pool': Array.from({ length: 16 }, (_, i) =>
    `assets/pixelab/landscape_v2/base/swamp_mud_pool/tiles/swamp_mud_pool__tile__v${String(i).padStart(3, '0')}.png`)
});

const PIXEL_BASE_WANG_VARIANTS = Object.freeze({
  'swamp/wet_mud': Array.from({ length: 16 }, (_, i) =>
    `assets/pixelab/landscape_v2/base/swamp_wet_mud/wang/swamp_wet_mud__wang_${i}__v000.png`),
  'swamp/mud_pool': Array.from({ length: 16 }, (_, i) =>
    `assets/pixelab/landscape_v2/base/swamp_mud_pool/wang/swamp_mud_pool__wang_${i}__v000.png`)
});

// ============================================================
// Image helpers
// ============================================================
function pixelBaseImage(src) {
  if (!src) return null;
  let image = pixelBaseCache.get(src);
  if (!image) {
    image = new Image();
    image.decoding = 'async';
    image.src = src;
    pixelBaseCache.set(src, image);
  }
  return image;
}

function preparedPixelBaseCanvas(src, baseFamily) {
  const image = pixelBaseImage(src);
  if (!image?.complete || !(image.naturalWidth || image.width)) return null;
  const width = image.naturalWidth || image.width;
  const height = image.naturalHeight || image.height;
  const key = `${src}|${baseFamily}|${width}x${height}|normalized-v1`;
  if (preparedPixelBaseCache.has(key)) return preparedPixelBaseCache.get(key);

  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const pctx = canvas.getContext('2d');
  pctx.imageSmoothingEnabled = false;
  pctx.drawImage(image, 0, 0);

  const data = pctx.getImageData(0, 0, width, height);
  const target = PIXEL_BASE_TARGET_RGB[baseFamily];
  if (target) {
    let r = 0, g = 0, b = 0, n = 0;
    for (let y = 2; y < height - 2; y++) {
      for (let x = 2; x < width - 2; x++) {
        const i = (y * width + x) * 4;
        const a = data.data[i + 3] / 255;
        if (a <= 0.01) continue;
        r += data.data[i] * a;
        g += data.data[i + 1] * a;
        b += data.data[i + 2] * a;
        n += a;
      }
    }
    if (n > 0) {
      const dr = target[0] - (r / n);
      const dg = target[1] - (g / n);
      const db = target[2] - (b / n);
      for (let i = 0; i < data.data.length; i += 4) {
        data.data[i] = clamp(data.data[i] + dr * 0.72, 0, 255);
        data.data[i + 1] = clamp(data.data[i + 1] + dg * 0.72, 0, 255);
        data.data[i + 2] = clamp(data.data[i + 2] + db * 0.72, 0, 255);
        data.data[i + 3] = 255;
      }
      pctx.putImageData(data, 0, 0);
    }
  }

  preparedPixelBaseCache.set(key, canvas);
  return canvas;
}

// Pre-warm caches
for (const variants of Object.values(PIXEL_BASE_WANG_VARIANTS)) {
  for (const src of variants) pixelBaseImage(src);
}
for (const variants of Object.values(PIXEL_BASE_TILE_VARIANTS)) {
  for (const src of variants) pixelBaseImage(src);
}

// ============================================================
// Spatially-coherent variant selection (2×2 macro cells)
// ============================================================
function pixelBaseInteriorVariantIndex(tile, variants) {
  if (!variants?.length) return 0;
  const macroX = Math.floor(tile.wx / 3);
  const macroY = Math.floor(tile.wy / 3);
  const primary = Math.floor(rand2(macroX, macroY, 16001) * variants.length) % variants.length;
  if (rand2(tile.wx, tile.wy, 16002) < 0.18) {
    return Math.floor(rand2(Math.floor(tile.wx / 2), Math.floor(tile.wy / 2), 16003) * variants.length) % variants.length;
  }
  return primary;
}

function pixelBaseTransform(tile, salt = 16004) {
  const h = Math.floor(rand2(tile.wx, tile.wy, salt) * 8) & 7;
  return {
    rotate: h & 3,
    flip: (h & 4) !== 0
  };
}

// ============================================================
// Draw prepared base with optional transform
// ============================================================
function drawPreparedPixelBase(ctx, canvas, tile, sx, sy, size, allowTransform) {
  const previousSmoothing = ctx.imageSmoothingEnabled;
  ctx.imageSmoothingEnabled = true;
  const inset = 2; // crop out 1px generator border
  const sourceWidth = Math.max(1, canvas.width - inset * 2);
  const sourceHeight = Math.max(1, canvas.height - inset * 2);
  if (!allowTransform) {
    ctx.drawImage(canvas, inset, inset, sourceWidth, sourceHeight, sx, sy, size, size);
    ctx.imageSmoothingEnabled = previousSmoothing;
    return;
  }

  const { rotate, flip } = pixelBaseTransform(tile);
  ctx.save();
  ctx.translate(sx + size / 2, sy + size / 2);
  ctx.rotate(rotate * Math.PI / 2);
  ctx.scale(flip ? -1 : 1, 1);
  ctx.drawImage(canvas, inset, inset, sourceWidth, sourceHeight, -size / 2, -size / 2, size, size);
  ctx.restore();
  ctx.imageSmoothingEnabled = previousSmoothing;
}

// ============================================================
// paintPixelLabBase — opaque terrain foundation
// ============================================================
function paintPixelLabBase(ctx, tile, recipe, sx, sy, size) {
  if (tile.pixelLabSkipBase) return false;
  const baseFamily = recipe?.base?.family ?? recipe?.baseFamily;
  const wangVariants = PIXEL_BASE_WANG_VARIANTS[baseFamily];
  const variants = PIXEL_BASE_TILE_VARIANTS[baseFamily];
  const foundationSrc = PIXEL_BASE_FOUNDATION_SRC[baseFamily] ?? variants?.[0];
  const mask = Number.isInteger(tile.pixelLabBaseMask) ? tile.pixelLabBaseMask : 15;
  const wangSrc = mask !== 15 ? wangVariants?.[mask] : null;

  // Use Wang tile if we're at a biome boundary, otherwise use variant
  const variantIndex = pixelBaseInteriorVariantIndex(tile, variants);
  const variantSrc = variants?.[variantIndex];
  const src = wangSrc || variantSrc || foundationSrc || wangVariants?.[15];
  if (!src) return false;

  tile.pixelLabBaseSrc = src;
  tile.pixelLabBaseVariantSrc = variantSrc && !wangSrc ? `v${String(variantIndex).padStart(3, '0')}` : '';
  tile.pixelLabBaseFamily = baseFamily ?? 'none';
  tile.pixelLabBaseMask = mask;

  const canvas = preparedPixelBaseCanvas(src, baseFamily);
  if (!canvas) return false;

  // Draw with transform for interior variants, no transform for Wang tiles
  drawPreparedPixelBase(ctx, canvas, tile, sx, sy, size, !wangSrc);
  return true;
}

// ============================================================
// paintSwampPixelLocalOverlays — micro details (reeds, flecks, moss)
// ============================================================
function paintSwampPixelLocalOverlays(ctx, tile, sx, sy, size) {
  const fertility = tile.climate?.fertility ?? 0.55;
  const vegetation = tile.climate?.vegetation ?? 0.55;
  const density = Math.max(0, Math.min(1, fertility * 0.45 + vegetation * 0.55));
  const moisture = tile.climate?.moisture ?? 0.65;
  const wetness = Math.max(0, Math.min(1, (moisture - 0.48) / 0.42));
  const mossChance = 0.18 + (fertility * 0.36 + vegetation * 0.44 + moisture * 0.20) * 0.40;

  // Moss flecks scattered across tile
  const baseSeed = tile.wx * 313 + tile.wy * 997;
  for (let gy = 0; gy < 8; gy++) {
    for (let gx = 0; gx < 8; gx++) {
      const cellSeed = baseSeed + gy * 19 + gx * 23;
      const px = sx + gx * 4 + ((cellSeed * 13) % 4);
      const py = sy + gy * 4 + ((cellSeed * 37) % 4);
      const presence = ((cellSeed * 53) % 100) / 100;
      if (presence < mossChance) {
        const alpha = 0.06 + (cellSeed % 5) * 0.04;
        ctx.fillStyle = 'rgba(52,96,48,' + alpha.toFixed(3) + ')';
        ctx.fillRect(px, py, 2 + (cellSeed % 3), 1 + (cellSeed % 2));
      }
    }
  }

  // Dark wet depression
  if (wetness > 0.42) {
    const wx = sx + Math.floor(rand2(tile.wx, tile.wy, 16080) * (size - 8));
    const wy = sy + Math.floor(rand2(tile.wx, tile.wy, 16081) * (size - 6));
    ctx.fillStyle = 'rgba(15,30,28,' + (0.18 + wetness * 0.16).toFixed(3) + ')';
    ctx.fillRect(wx, wy, Math.max(3, Math.floor(size * 0.14)), Math.max(2, Math.floor(size * 0.06)));
  }

  // Grass blades
  if (density > 0.25) {
    const count = 1 + Math.floor(density * 2 + rand2(tile.wx, tile.wy, 16090) * 2);
    for (let i = 0; i < count; i++) {
      const px = sx + Math.floor(rand2(tile.wx, tile.wy, 16091 + i * 11) * (size - 4));
      const py = sy + Math.floor(rand2(tile.wx, tile.wy, 16092 + i * 11) * (size - 4));
      const h = Math.max(2, Math.floor(size * (0.06 + rand2(tile.wx, tile.wy, 16093 + i * 11) * 0.08)));
      ctx.strokeStyle = 'rgba(60,130,55,0.35)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(px, py + h);
      ctx.lineTo(px + 1, py);
      ctx.stroke();
    }
  }
}

// ============================================================
// paintSwampMacroObjects — large visible objects
// ============================================================
function paintSwampMacroObjects(ctx, tile, sx, sy, size) {
  if (tile.biome !== 'swamp') return;
  const n = 1 + Math.floor(rand2(tile.wx, tile.wy, 16500) * 2);
  for (let i = 0; i < n; i++) {
    const k = Math.floor(rand2(tile.wx, tile.wy, 16520 + i) * 5);
    const x = sx + Math.floor(rand2(tile.wx, tile.wy, 16510 + i * 7) * (size - 14)) + 7;
    const y = sy + Math.floor(rand2(tile.wx, tile.wy, 16511 + i * 7) * (size - 14)) + 7;
    ctx.save();
    if (k === 0) {
      const h = Math.floor(size * (0.35 + rand2(tile.wx, tile.wy, 16530 + i) * 0.30));
      const w = Math.floor(size * (0.08 + rand2(tile.wx, tile.wy, 16531 + i) * 0.06));
      ctx.fillStyle = 'rgba(36,22,16,0.95)';
      ctx.fillRect(x - Math.floor(w / 2), y - h, w, h);
      ctx.fillStyle = 'rgba(52,34,22,0.70)';
      ctx.fillRect(x - Math.floor(w / 2) + 1, y - h + 1, Math.max(1, w - 2), Math.max(1, Math.floor(h * 0.5)));
    } else if (k === 1) {
      const sw = Math.floor(size * (0.18 + rand2(tile.wx, tile.wy, 16540 + i) * 0.16));
      const sh = Math.floor(size * (0.06 + rand2(tile.wx, tile.wy, 16541 + i) * 0.05));
      ctx.fillStyle = 'rgba(52,34,22,0.95)';
      ctx.fillRect(x - Math.floor(sw / 2), y - Math.floor(sh / 2), sw, sh);
      ctx.fillStyle = 'rgba(72,48,30,0.85)';
      ctx.fillRect(x - Math.floor(sw * 0.3), y - Math.floor(sh * 0.3), Math.floor(sw * 0.6), Math.floor(sh * 0.6));
    } else if (k === 2) {
      const lw = Math.floor(size * (0.22 + rand2(tile.wx, tile.wy, 16550 + i) * 0.22));
      const lh = Math.floor(size * (0.06 + rand2(tile.wx, tile.wy, 16551 + i) * 0.05));
      ctx.fillStyle = 'rgba(48,28,18,0.92)';
      ctx.fillRect(x - Math.floor(lw / 2), y - Math.floor(lh / 2), lw, lh);
      ctx.fillStyle = 'rgba(30,16,10,0.50)';
      ctx.fillRect(x - Math.floor(lw * 0.4), y - Math.floor(lh * 0.1), Math.floor(lw * 0.8), 1);
    } else if (k === 3) {
      const rw = Math.floor(size * (0.12 + rand2(tile.wx, tile.wy, 16560 + i) * 0.14));
      const rh = Math.floor(size * (0.08 + rand2(tile.wx, tile.wy, 16561 + i) * 0.08));
      ctx.fillStyle = 'rgba(68,64,58,0.92)';
      ctx.fillRect(x - Math.floor(rw / 2), y - Math.floor(rh / 2), rw, rh);
      ctx.fillStyle = 'rgba(98,94,84,0.50)';
      ctx.fillRect(x - Math.floor(rw * 0.3), y - Math.floor(rh * 0.3), Math.floor(rw * 0.4), Math.floor(rh * 0.3));
    } else {
      const hw = Math.floor(size * (0.14 + rand2(tile.wx, tile.wy, 16570 + i) * 0.14));
      const hh = Math.floor(size * (0.04 + rand2(tile.wx, tile.wy, 16571 + i) * 0.05));
      ctx.fillStyle = 'rgba(42,118,42,0.80)';
      ctx.fillRect(x - Math.floor(hw / 2), y - Math.floor(hh / 2), hw, hh);
      ctx.fillStyle = 'rgba(62,148,52,0.60)';
      ctx.fillRect(x - Math.floor(hw * 0.3), y - Math.floor(hh * 0.4), Math.floor(hw * 0.6), Math.floor(hh * 0.6));
    }
    ctx.restore();
  }
}

// ============================================================
// assembleLandscapeLayers — supplementary decoration
// ============================================================
function assembleLandscapeLayers(ctx, tile, sx, sy, size, sun, atlas, patch) {
  const e = tile.climate ? tile.climate.elevation : 0.5;
  const f = tile.climate ? tile.climate.fertility : 0.5;
  const v = tile.climate ? tile.climate.vegetation : 0.5;
  const m = tile.climate ? tile.climate.moisture : 0.5;
  const b = tile.biome;

  // Elevation steps on steep terrain
  if (e > 0.65 && rand2(tile.wx, tile.wy, 4000) < (e - 0.6) * 7) {
    ctx.fillStyle = 'rgba(40,35,30,0.12)';
    ctx.fillRect(sx, sy + Math.floor(size * 0.5), size, Math.floor(size * 0.08));
  }

  // Geology rocks on high/rocky terrain
  const isRocky = b === 'hills' || b === 'mountains' || b === 'volcanic' || e > 0.60;
  if (isRocky && rand2(tile.wx, tile.wy, 5000) < 0.3) {
    const rx = sx + Math.floor(rand2(tile.wx, tile.wy, 5001) * (size - 6));
    const ry = sy + Math.floor(rand2(tile.wx, tile.wy, 5002) * (size - 4));
    ctx.fillStyle = 'rgba(70,65,58,0.30)';
    ctx.fillRect(rx, ry, 4 + Math.floor(rand2(tile.wx, tile.wy, 5003) * 4), 2 + Math.floor(rand2(tile.wx, tile.wy, 5004) * 2));
  }

  // Ground cover / moss patches on fertile wet ground
  if (f > 0.4 && m > 0.4 && rand2(tile.wx, tile.wy, 6000) < 0.35) {
    const gx = sx + Math.floor(rand2(tile.wx, tile.wy, 6001) * (size - 6));
    const gy = sy + Math.floor(rand2(tile.wx, tile.wy, 6002) * (size - 5));
    ctx.fillStyle = 'rgba(55,110,48,0.15)';
    ctx.fillRect(gx, gy, 3 + Math.floor(rand2(tile.wx, tile.wy, 6004) * 4), 2 + Math.floor(rand2(tile.wx, tile.wy, 6005) * 2));
  }

  // Grass tufts on vegetated ground
  if (v > 0.4 && rand2(tile.wx, tile.wy, 6100) < 0.40) {
    const count = 1 + Math.floor(rand2(tile.wx, tile.wy, 6101) * 2);
    for (let gi = 0; gi < count; gi++) {
      const gx = sx + Math.floor(rand2(tile.wx, tile.wy, 6110 + gi) * size);
      const gy = sy + Math.floor(rand2(tile.wx, tile.wy, 6120 + gi) * size);
      const gh = Math.floor(size * (0.08 + rand2(tile.wx, tile.wy, 6130 + gi) * 0.10));
      ctx.strokeStyle = 'rgba(60,130,55,0.35)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(gx, gy + gh);
      ctx.lineTo(gx + 1, gy);
      ctx.stroke();
    }
  }

  // Bushes in forest biomes
  const isForest = b === 'forest' || b === 'dense_forest' || b === 'tropical_forest' || b === 'taiga' || b === 'swamp';
  if (isForest && v > 0.45 && rand2(tile.wx, tile.wy, 7000) < 0.15) {
    const bx = sx + Math.floor(rand2(tile.wx, tile.wy, 7001) * (size - 8));
    const by = sy + Math.floor(rand2(tile.wx, tile.wy, 7002) * (size - 6));
    ctx.fillStyle = 'rgba(28,80,34,0.50)';
    ctx.beginPath();
    ctx.arc(bx + 4, by + 4, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(40,110,48,0.40)';
    ctx.beginPath();
    ctx.arc(bx + 3, by + 3, 3, 0, Math.PI * 2);
    ctx.fill();
  }

  // Trees in forest biomes
  if (isForest && v > 0.50 && rand2(tile.wx, tile.wy, 8000) < 0.08 + v * 0.06) {
    const tx = sx + Math.floor(rand2(tile.wx, tile.wy, 8001) * (size - 6));
    const ty = sy + Math.floor(rand2(tile.wx, tile.wy, 8002) * (size - 8));
    const th = Math.floor(size * (0.35 + rand2(tile.wx, tile.wy, 8003) * 0.25));
    ctx.fillStyle = 'rgba(42,28,18,0.70)';
    ctx.fillRect(tx, ty + Math.floor(size * 0.08), 3, th - Math.floor(size * 0.08));
    ctx.fillStyle = 'rgba(30,90,36,0.50)';
    ctx.beginPath();
    ctx.arc(tx + 1, ty + Math.floor(size * 0.04), Math.floor(size * 0.08), 0, Math.PI * 2);
    ctx.fill();
  }
}

// ============================================================
// Exported utilities
// ============================================================
export function shade(hex, amount) {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  return 'rgb(' + clamp(r + amount) + ',' + clamp(g + amount) + ',' + clamp(b + amount) + ')';
}

export function tint(color, tintColor, ambient = 1) {
  if (!tintColor) return color;
  const channels = color.match(/\d+/g);
  if (!channels || channels.length < 3) return color;
  const r = Math.floor(parseInt(channels[0]) * (tintColor.r * ambient + 1 - ambient));
  const g = Math.floor(parseInt(channels[1]) * (tintColor.g * ambient + 1 - ambient));
  const b = Math.floor(parseInt(channels[2]) * (tintColor.b * ambient + 1 - ambient));
  return 'rgb(' + r + ',' + g + ',' + b + ')';
}

export function parseRgb(color) {
  const channels = color.match(/\d+/g);
  return channels ? [parseInt(channels[0]), parseInt(channels[1]), parseInt(channels[2])] : [0, 0, 0];
}

function clamp(value, min = 0, max = 255) {
  if (typeof value !== 'number' || isNaN(value)) return min;
  return Math.max(min, Math.min(max, Math.round(value)));
}

function coherentPatch(wx, wy, biome) {
  return smoothNoise(wx * 0.5, wy * 0.5, 5000);
}

function detailDensity(biome) {
  const dense = ['forest', 'dense_forest', 'tropical_forest', 'swamp', 'taiga'];
  const medium = ['grassland', 'savanna', 'steppe', 'mystic', 'hills'];
  if (dense.includes(biome)) return 0.75;
  if (medium.includes(biome)) return 0.50;
  return 0.30;
}

// ============================================================
// paintTerrainTile — main tile render entry
// ============================================================
export function paintTerrainTile(ctx, tile, sx, sy, size, sun, focusElevation, compositor = null, timeSeconds = 0, atlas = null) {
  if (!ctx || !tile) return;
  const palette = paletteFor(tile.biome);
  const patch = coherentPatch(tile.wx, tile.wy, tile.biome);
  const base = palette[Math.min(palette.length - 1, Math.floor(patch * palette.length))];
  const e = tile.climate ? tile.climate.elevation : 0.5;
  const elevationShade = (e - 0.5) * 0.18;
  let depthFade = 0;
  if (focusElevation !== undefined) {
    depthFade = Math.max(0, focusElevation - e - 0.08) * 0.50;
  }
  ctx.fillStyle = shade(base, elevationShade + depthFade);
  ctx.fillRect(sx, sy, size, size);

  // Recipe-driven PixelLab base
  const recipe = null; // will be populated from landscape-recipe when integrated
  const pixelBasePainted = paintPixelLabBase(ctx, tile, recipe, sx, sy, size);

  if (!pixelBasePainted) {
    // Fallback: biome texture + micro layers + landscape layers
    paintBiomeTexture(ctx, tile, sx, sy, size, sun, palette);
    assembleLandscapeLayers(ctx, tile, sx, sy, size, sun, atlas, patch);
  } else {
    // PixelLab base painted — add local swamp overlays
    if (tile.biome === 'swamp') {
      paintSwampPixelLocalOverlays(ctx, tile, sx, sy, size);
      paintSwampMacroObjects(ctx, tile, sx, sy, size);
    }
    assembleLandscapeLayers(ctx, tile, sx, sy, size, sun, atlas, patch);
  }

  if (compositor && atlas) {
    const sig = compositor.terrainSignature(tile);
    if (sig) {
      const hash = sig.variant % 360;
      ctx.fillStyle = 'hsla(' + hash + ',45%,62%,0.08)';
      ctx.fillRect(sx, sy, size, size);
    }
  }
}

export function paintCompositorDebugLayer(ctx, signature, sx, sy, size) {
  const hash = signature.variant % 360;
  ctx.fillStyle = 'hsla(' + hash + ',45%,62%,0.08)';
  ctx.fillRect(sx, sy, size, size);
}

export function paintBiomeTexture(ctx, tile, sx, sy, size, sun, renderPalette) {
